fn selection_signal_name(component: &Value) -> Option<&str> {
    let name = component.as_str().or_else(|| {
        component
            .get("n")
            .or_else(|| component.get("name"))
            .and_then(Value::as_str)
            .or_else(|| {
                component
                    .as_array()
                    .and_then(|items| items.first())
                    .and_then(Value::as_str)
            })
    })?;
    Some(expand_compact_selection_signal(name))
}

